html:
{#- Cash Handover Receipt (ACC-09, 22 Oct 2026): the paper the receiver signs by hand when a branch hands its cash
    over. Arabic, right to left, one A5 or A4 page. No electronic signature: the signed paper is scanned back onto
    the hand-over. -#}
{%- set company = frappe.db.get_value("Cost Center", doc.branch, "company") -%}
{%- set company_name = frappe.db.get_value("Company", company, "company_name") or company -%}
{%- set giver = frappe.db.get_value("User", doc.handed_over_by, "full_name") or doc.handed_over_by -%}
{%- set receiver = frappe.db.get_value("User", doc.receiver, "full_name") or doc.receiver -%}
{%- set branch = (doc.branch or "").rsplit(" - ", 1)[0] -%}
{%- set box = (doc.treasury or "").rsplit(" - ", 1)[0] -%}
{%- set kind = "المالك" if doc.receiver_kind == "Owner" else "المحاسب" -%}
<div dir="rtl" lang="ar" class="cho">
	<style>
		.cho { font-family: "Cairo", "Noto Naskh Arabic", "Tahoma", sans-serif; font-size: 14px; color: #111; text-align: right; }
		.cho h1 { font-size: 22px; margin: 0 0 4px; text-align: center; }
		.cho .company { text-align: center; font-size: 16px; font-weight: bold; margin-bottom: 2px; }
		.cho .sub { text-align: center; color: #555; margin-bottom: 14px; }
		.cho table.meta { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
		.cho table.meta td { border: 1px solid #999; padding: 7px 9px; vertical-align: top; }
		.cho table.meta td.k { width: 28%; background: #f3f3f3; font-weight: bold; }
		.cho .amount { font-size: 20px; font-weight: bold; direction: ltr; unicode-bidi: embed; }
		.cho .words { font-weight: bold; }
		.cho .stmt { margin: 14px 0; line-height: 1.9; }
		.cho .sign { width: 100%; margin-top: 26px; border-collapse: collapse; }
		.cho .sign td { width: 50%; padding: 6px 10px; vertical-align: top; }
		.cho .line { border-bottom: 1px dotted #333; height: 48px; margin: 6px 0 4px; }
		.cho .mark { text-align: center; font-size: 26px; color: #b00; border: 3px solid #b00; padding: 4px; margin-bottom: 10px; }
		.cho .foot { margin-top: 18px; font-size: 11px; color: #666; text-align: center; }
	</style>
	{%- if doc.docstatus == 0 %}<div class="mark">مسودة — لا يُعتد بها</div>{% endif -%}
	{%- if doc.docstatus == 2 %}<div class="mark">ملغى</div>{% endif -%}
	<div class="company">{{ company_name }}</div>
	<h1>إيصال استلام نقدية</h1>
	<div class="sub">تسليم نقدية الفرع الأسبوعي — {{ branch }}</div>

	<table class="meta">
		<tr><td class="k">رقم الإيصال</td><td>{{ doc.name }}</td></tr>
		<tr><td class="k">الفرع</td><td>{{ branch }}</td></tr>
		<tr><td class="k">من خزينة</td><td>{{ box }}</td></tr>
		<tr><td class="k">التاريخ والوقت</td><td>{{ frappe.format_value(doc.handover_date, {"fieldtype": "Date"}) }} — {{ (doc.handover_time | string)[:5] }}</td></tr>
		<tr><td class="k">المبلغ بالأرقام</td><td><span class="amount">{{ frappe.format_value(doc.amount, {"fieldtype": "Currency"}) }}</span></td></tr>
		<tr><td class="k">المبلغ بالحروف</td><td class="words">{{ doc.amount_in_words }}</td></tr>
		<tr><td class="k">سلّمه</td><td>{{ giver }}</td></tr>
		<tr><td class="k">استلمه ({{ kind }})</td><td>{{ receiver }}</td></tr>
		{%- if doc.notes %}<tr><td class="k">ملاحظات</td><td>{{ doc.notes }}</td></tr>{% endif %}
	</table>

	<div class="stmt">
		أقر أنا <b>{{ receiver }}</b> بأنني استلمت من <b>{{ giver }}</b> مبلغًا نقديًا قدره
		<b>{{ frappe.format_value(doc.amount, {"fieldtype": "Currency"}) }}</b> ({{ doc.amount_in_words }})
		من خزينة {{ box }}، وقد قمت بعدّه وتحققت منه.
	</div>

	<table class="sign">
		<tr>
			<td>
				<b>توقيع المستلم ({{ kind }})</b>
				<div class="line"></div>
				الاسم: {{ receiver }}<br>
				التاريخ: ........ / ........ / ............
			</td>
			<td>
				<b>توقيع المُسلِّم</b>
				<div class="line"></div>
				الاسم: {{ giver }}
			</td>
		</tr>
	</table>
	<div class="foot">بعد التوقيع: صوّر الإيصال أو امسحه ضوئيًا وأرفقه على {{ doc.name }} في النظام، ثم يؤكد المستلم الاستلام.</div>
</div>
